 // EECS 348 Assignment 4 - Sudoku Solver
 // This program uses object-oriented programming and recursive backtracking
 // to solve Sudoku puzzles by checking possible values in each empty cell.
 // The program finds and prints all valid solutions for each puzzle.
 // Inputs: puzzle1.txt, puzzle2.txt, puzzle3.txt, puzzle4.txt, puzzle5.txt
 // Outputs: Original puzzle, all valid solutions, or "No solution found"
 // Source: Code generated by ChatGPT (OpenAI)
 // Author: Madelyn Armitage
 // Creation Date: 10/12/2026
 // No human collaborators
 
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

class Sudoku {
private:
    int board[9][9]{};
    int solutionCount = 0;

    // Check the row, column, and 3x3 block for a repeated number.
    bool canPlace(int row, int col, int number) const {
        for (int i = 0; i < 9; i++) {
            if (i != col && board[row][i] == number) {
                return false;
            }
            if (i != row && board[i][col] == number) {
                return false;
            }
        }

        int startRow = (row / 3) * 3;
        int startCol = (col / 3) * 3;

        for (int r = startRow; r < startRow + 3; r++) {
            for (int c = startCol; c < startCol + 3; c++) {
                if ((r != row || c != col) &&
                    board[r][c] == number) {
                    return false;
                }
            }
        }
        return true;
    }

    // Validate the original puzzle.
    bool startingBoardIsValid() const {
        for (int row = 0; row < 9; row++) {
            for (int col = 0; col < 9; col++) {
                if (board[row][col] != 0 &&
                    !canPlace(row, col, board[row][col])) {
                    return false;
                }
            }
        }
        return true;
    }

    // Recursive depth-first search with backtracking.
    void solveRecursive() {
        int bestRow = -1;
        int bestCol = -1;
        int fewestCandidates = 10;

        // Find an empty cell with the fewest possible numbers.
        for (int row = 0; row < 9; row++) {
            for (int col = 0; col < 9; col++) {
                if (board[row][col] == 0) {
                    int candidates = 0;

                    for (int number = 1; number <= 9; number++) {
                        if (canPlace(row, col, number)) {
                            candidates++;
                        }
                    }

                    if (candidates == 0) {
                        return; // Dead end: backtrack.
                    }

                    if (candidates < fewestCandidates) {
                        fewestCandidates = candidates;
                        bestRow = row;
                        bestCol = col;
                    }
                }
            }
        }

        // No empty cells means a solution was found.
        if (bestRow == -1) {
            solutionCount++;
            cout << "Solution " << solutionCount << ":\n";
            printBoard();
            cout << '\n';
            return;
        }

        // Try every possible number.
        for (int number = 1; number <= 9; number++) {
            if (canPlace(bestRow, bestCol, number)) {
                board[bestRow][bestCol] = number;

                solveRecursive();

                // Undo the attempt to find other solutions.
                board[bestRow][bestCol] = 0;
            }
        }
    }

public:
    // Read a Sudoku puzzle from a text file.
    bool loadPuzzle(const string& filename) {
        ifstream input(filename);

        if (!input) {
            return false;
        }

        solutionCount = 0;

        for (int row = 0; row < 9; row++) {
            for (int col = 0; col < 9; col++) {
                char value;

                if (!(input >> value)) {
                    return false;
                }

                if (value == '_') {
                    board[row][col] = 0;
                }
                else if (value >= '1' && value <= '9') {
                    board[row][col] = value - '0';
                }
                else {
                    return false;
                }
            }
        }

        return true;
    }

    // Print the current Sudoku board.
    void printBoard() const {
        for (int row = 0; row < 9; row++) {
            for (int col = 0; col < 9; col++) {
                if (board[row][col] == 0) {
                    cout << '_';
                }
                else {
                    cout << board[row][col];
                }

                if (col != 8) {
                    cout << ' ';
                }
            }
            cout << '\n';
        }
    }

    // Start solving and display the result.
    void solve() {
        solutionCount = 0;

        if (startingBoardIsValid()) {
            solveRecursive();
        }

        if (solutionCount == 0) {
            cout << "No solution found\n";
        }
        else {
            cout << "Solutions found: "
                 << solutionCount << '\n';
        }
    }
};

int main() {
    const string filenames[5] = {
        "puzzle1.txt",
        "puzzle2.txt",
        "puzzle3.txt",
        "puzzle4.txt",
        "puzzle5.txt"
    };

    for (const string& filename : filenames) {
        Sudoku puzzle;

        cout << "File: " << filename << "\n";

        if (!puzzle.loadPuzzle(filename)) {
            cout << "Unable to read puzzle file.\n\n";
            continue;
        }

        cout << "Original puzzle:\n";
        puzzle.printBoard();
        cout << '\n';

        puzzle.solve();

        cout << "\n-----------------------------\n\n";
    }

    return 0;
}
